const u=n=>{const t=Number(typeof n=="string"?n.replace(/[₹,\s]/g,""):n);return Number.isFinite(t)?Math.max(0,Math.round(t)):0},o=n=>{const t=Number(n);return Number.isFinite(t)?Math.round(t):0},e=n=>{const t=o(n),r=t<0?"-":"",s=String(Math.abs(t));if(s.length<=3)return r+s;const i=s.slice(-3),c=s.slice(0,-3).replace(/\B(?=(\d{2})+(?!\d))/g,",");return`${r}${c},${i}`},a=n=>{const t=o(n);return t<0?`-₹${e(-t)}`:`₹${e(t)}`};export{u as a,a as f,o as t};
